+
+        service.cancel(reservation.id());
+
+        List<Message> sent = sentMessages.all();
+        assertEquals(messagesBefore + 2, sent.size());
+        List<Message> cancelMessages = sent.subList(messagesBefore, sent.size());
+        Message housekeepingMessage = cancelMessages.stream().filter(m -> m.to().equals("governanca@pousadamarealta.com.br")).findFirst().orElseThrow();
