+        assertEquals("Reembolso - reserva " + reservation.id(), financeMessage.subject());
+        assertTrue(financeMessage.body().contains("R$ 1.169,70"));
+    }
+
+    @Test
+    void notifiesOnlyHousekeepingOnNonRefundableCancellation() {
+        Reservation reservation = service.create(stay(201, "2027-03-10", "2027-03-13", 2, RatePlan.NON_REFUNDABLE));
+        service.confirm(reservation.id());
+        int messagesBefore = sentMessages.all().size();
+
+        service.cancel(reservation.id());
+
+        List<Message> sent = sentMessages.all();
+        assertEquals(messagesBefore + 1, sent.size());
+        Message housekeepingMessage = sent.get(sent.size() - 1);
+        assertEquals("governanca@pousadamarealta.com.br", housekeepingMessage.to());
+        assertEquals("Reserva cancelada - quarto 201", housekeepingMessage.subject());
+    }
+
+    @Test
+    void doesNotNotifyOnPendingCancellation() {
+        Reservation reservation = service.create(stay(201, "2027-03-10", "2027-03-13", 2, RatePlan.STANDARD));
+
+        service.cancel(reservation.id());
+
+        List<Message> sent = sentMessages.all();
+        assertEquals(0, sent.size());
+    }
 }
