   110	        CreateReservationRequest body;
   111	        try {
   112	            body = ctx.bodyAsClass(CreateReservationRequest.class);
   113	        } catch (Exception unreadableBody) { // Jackson's own exceptions are checked, but reach here unwrapped
   114	            throw new HotelException(ErrorCode.INVALID_REQUEST, "the body is not a valid reservation request");
   115	        }
   116	        if (body == null
   117	                || body.roomNumber() == null
   118	                || isBlank(body.guestName())
   119	                || isBlank(body.guestEmail())
   120	                || isBlank(body.guestCpf())
   121	                || body.checkIn() == null
   122	                || body.checkOut() == null
   123	                || body.guests() == null
   124	                || body.ratePlan() == null) {
   125	            throw new HotelException(ErrorCode.INVALID_REQUEST, "every field of the reservation is required");
   126	        }
   127	        Guest guest = new Guest(body.guestName(), body.guestEmail(), body.guestCpf());
   128	        return new NewReservation(
   129	                body.roomNumber(), guest, body.checkIn(), body.checkOut(), body.guests(), body.ratePlan());
   130	    }
   131	
   132	    private static long reservationId(Context ctx) {
   133	        String id = ctx.pathParam("id");
   134	        try {
   135	            return Long.parseLong(id);
   136	        } catch (NumberFormatException notANumber) {
   137	            throw new HotelException(ErrorCode.RESERVATION_NOT_FOUND, "reservation " + id + " does not exist");
   138	        }
   139	    }
   140	
   141	    private static LocalDate readDate(Context ctx) {
   142	        String date = requiredQueryParam(ctx, "date");
   143	        try {
   144	            return LocalDate.parse(date);
   145	        } catch (DateTimeParseException badDate) {
   146	            throw new HotelException(ErrorCode.INVALID_REQUEST, "'" + date + "' is not a date (yyyy-MM-dd)");
   147	        }
   148	    }
   149	
   150	    private static YearMonth readMonth(Context ctx) {
   151	        String month = requiredQueryParam(ctx, "month");
   152	        try {
   153	            return YearMonth.parse(month);
   154	        } catch (DateTimeParseException badMonth) {
   155	            throw new HotelException(ErrorCode.INVALID_REQUEST, "'" + month + "' is not a month (yyyy-MM)");
   156	        }
   157	    }
   158	
   159	    private static String requiredQueryParam(Context ctx, String name) {
   160	        String value = ctx.queryParam(name);
   161	        if (value == null) {
   162	            throw new HotelException(ErrorCode.INVALID_REQUEST, "the query parameter '" + name + "' is required");
   163	        }
   164	        return value;
